class Solution {
    long long pw(long long b, long long e, long long m){
        long long r=1; b%=m;
        while(e>0){ if(e&1) r=r*b%m; b=b*b%m; e>>=1; }
        return r;
    }
public:
    vector<int> getFinalState(vector<int>& nums, int k, int multiplier) {
        const long long MOD=1e9+7; int n=nums.size();
        if(multiplier==1){ vector<int> r; for(int x:nums) r.push_back(x%MOD); return r; }
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
        for(int i=0;i<n;++i) pq.push({nums[i],i});
        long long mx=*max_element(nums.begin(),nums.end());
        vector<long long> cnt(n,0), cur(n);
        while(k>0 && pq.top().first*multiplier<=mx){
            auto [v,i]=pq.top(); pq.pop();
            cnt[i]++; pq.push({v*multiplier,i}); --k;
        }
        long long base=k/n, extra=k%n;
        vector<int> ord(n); iota(ord.begin(),ord.end(),0);
        for(int i=0;i<n;++i) cur[i]=nums[i]*pw(multiplier,cnt[i],(long long)4e18); // exact: values <= 1e9
        // recompute exact current values without mod (they fit in long long)
        for(int i=0;i<n;++i){ long long v=nums[i]; for(long long t=0;t<cnt[i];++t) v*=multiplier; cur[i]=v; }
        sort(ord.begin(),ord.end(),[&](int a,int b){ return cur[a]!=cur[b]?cur[a]<cur[b]:a<b; });
        vector<int> res(n);
        for(int rk=0;rk<n;++rk){ int i=ord[rk];
            res[i]=(int)(nums[i]%MOD*pw(multiplier,cnt[i]+base+(rk<extra?1:0),MOD)%MOD);
        }
        return res;
    }
};

