class Solution {
    private long pw(long b, long e, long m){
        long r=1; b%=m;
        while(e>0){ if((e&1)==1) r=r*b%m; b=b*b%m; e>>=1; }
        return r;
    }
    public int[] getFinalState(int[] nums, int k, int multiplier) {
        final long MOD=1000000007L; int n=nums.length;
        if(multiplier==1){ int[] r=new int[n]; for(int i=0;i<n;++i) r[i]=nums[i]%1000000007; return r; }
        PriorityQueue<long[]> pq=new PriorityQueue<>((a,b)->a[0]!=b[0]?Long.compare(a[0],b[0]):Long.compare(a[1],b[1]));
        for(int i=0;i<n;++i) pq.add(new long[]{nums[i],i});
        long mx=0; for(int x:nums) mx=Math.max(mx,x);
        long[] cnt=new long[n], cur=new long[n];
        while(k>0 && pq.peek()[0]*multiplier<=mx){
            long[] t=pq.poll(); cnt[(int)t[1]]++; pq.add(new long[]{t[0]*multiplier,t[1]}); --k;
        }
        long base=k/n, extra=k%n;
        Integer[] ord=new Integer[n];
        for(int i=0;i<n;++i){ ord[i]=i; long v=nums[i]; for(long t=0;t<cnt[i];++t) v*=multiplier; cur[i]=v; }
        java.util.Arrays.sort(ord,(a,b)-> cur[a]!=cur[b] ? Long.compare(cur[a],cur[b]) : Integer.compare(a,b));
        int[] res=new int[n];
        for(int rk=0;rk<n;++rk){ int i=ord[rk];
            res[i]=(int)(nums[i]%MOD*pw(multiplier,cnt[i]+base+(rk<extra?1:0),MOD)%MOD);
        }
        return res;
    }
}

