var getFinalState = function(nums, k, multiplier) {
    const MOD = 1000000007n, n = nums.length;
    if (multiplier === 1) return nums.map(x => x % 1000000007);
    const h = nums.map((v, i) => [v, i]);
    const less = (a, b) => a[0] < b[0] || (a[0] === b[0] && a[1] < b[1]);
    const push = (p) => { h.push(p); let i = h.length - 1;
        while (i > 0) { const pa = (i - 1) >> 1; if (!less(h[i], h[pa])) break; [h[pa], h[i]] = [h[i], h[pa]]; i = pa; } };
    const pop = () => { const top = h[0], last = h.pop();
        if (h.length) { h[0] = last; let i = 0;
            for (;;) { const l = 2*i+1, r = l+1; let s = i;
                if (l < h.length && less(h[l], h[s])) s = l;
                if (r < h.length && less(h[r], h[s])) s = r;
                if (s === i) break; [h[s], h[i]] = [h[i], h[s]]; i = s; } }
        return top; };
    const mx = Math.max(...nums);
    const cnt = new Array(n).fill(0);
    while (k > 0 && h[0][0] * multiplier <= mx) {
        const [v, i] = pop(); cnt[i]++; push([v * multiplier, i]); k--;
    }
    const base = Math.floor(k / n), extra = k % n;
    const ord = [...Array(n).keys()];
    const cur = ord.map(i => { let v = nums[i]; for (let t = 0; t < cnt[i]; ++t) v *= multiplier; return v; });
    ord.sort((a, b) => cur[a] !== cur[b] ? cur[a] - cur[b] : a - b);
    const pw = (b, e) => { let r = 1n; b %= MOD;
        while (e > 0n) { if (e & 1n) r = r * b % MOD; b = b * b % MOD; e >>= 1n; } return r; };
    const res = new Array(n);
    for (let rk = 0; rk < n; ++rk) {
        const i = ord[rk];
        const e = BigInt(cnt[i] + base + (rk < extra ? 1 : 0));
        res[i] = Number(BigInt(nums[i]) * pw(BigInt(multiplier), e) % MOD);
    }
    return res;
};

