class Solution:
    def getFinalState(self, nums: List[int], k: int, multiplier: int) -> List[int]:
        import heapq
        MOD = 10**9 + 7
        h = [(v, i) for i, v in enumerate(nums)]
        heapq.heapify(h)
        for _ in range(k):
            v, i = heapq.heappop(h)
            heapq.heappush(h, (v * multiplier, i))
        res = [0] * len(nums)
        for v, i in h:
            res[i] = v % MOD
        return res

